65	static void WriteOutputFile(const Module *M, const ModuleSummaryIndex *Index) {
66	  // Infer the output filename if needed.
67	  if (OutputFilename.empty()) {
68	    if (InputFilename == "-") {
69	      OutputFilename = "-";
70	    } else {
71	      StringRef IFN = InputFilename;
72	      OutputFilename = (IFN.ends_with(".ll") ? IFN.drop_back(3) : IFN).str();
73	      OutputFilename += ".bc";
74	    }
75	  }
76	
77	  std::error_code EC;
78	  std::unique_ptr<ToolOutputFile> Out(
79	      new ToolOutputFile(OutputFilename, EC, sys::fs::OF_None));
80	  if (EC) {
81	    errs() << EC.message() << '\n';
82	    exit(1);
83	  }
84	
85	  if (Force || !CheckBitcodeOutputToConsole(Out->os())) {
86	    const ModuleSummaryIndex *IndexToWrite = nullptr;
87	    // Don't attempt to write a summary index unless it contains any entries or
88	    // has non-zero flags. The latter is used to assemble dummy index files for
89	    // skipping modules by distributed ThinLTO backends. Otherwise we get an empty
90	    // summary section.
91	    if (Index && (Index->begin() != Index->end() || Index->getFlags()))
92	      IndexToWrite = Index;
93	    if (!IndexToWrite || (M && (!M->empty() || !M->global_empty())))
94	      // If we have a non-empty Module, then we write the Module plus
95	      // any non-null Index along with it as a per-module Index.
96	      // If both are empty, this will give an empty module block, which is
97	      // the expected behavior.
98	      WriteBitcodeToFile(*M, Out->os(), /* ShouldPreserveUseListOrder */ true,
99	                         IndexToWrite, EmitModuleHash);
100	    else
101	      // Otherwise, with an empty Module but non-empty Index, we write a
102	      // combined index.
103	      writeIndexToFile(*IndexToWrite, Out->os());
